const body = $input.first().json.body;

const borrowerFirst = body.borrower_first_name || '[Borrower]';
const borrowerLast = body.borrower_last_name || '';
const coBorrowerFirst = body.co_borrower_first_name || '';
const borrowerEmail = body.email || '';
const loanId = body.loan_id || '';
const loanAmount = Number(body.loan_amount) || 0;
const rate = Number(body.rate) || 0;
const piPayment = Number(body.pi_payment) || 0;
const totalMonthly = Number(body.total_monthly_payment) || 0;
const cashToClose = Number(body.cash_to_close) || 0;
const lockPeriod = body.lock_period || '30 days';
const escrow = body.escrow || 'Active';

const coBorrowerSalutation = coBorrowerFirst ? ' and ' + coBorrowerFirst : '';

const fmt = (n) => Math.abs(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const loanAmountFmt = '$' + fmt(loanAmount);
const piPaymentFmt = '$' + fmt(piPayment) + '/mo';
const totalMonthlyFmt = '$' + fmt(totalMonthly) + '/mo';
const cashAmt = '$' + fmt(cashToClose);
const cashLabel = cashToClose < 0 ? 'Cash Back at Closing' : 'Cash to Close';

const escrowRow = escrow === 'Waived'
  ? '<tr style="border-bottom:1px solid #f3f4f6;"><td style="padding:8px 12px;color:#6b7280;font-size:14px;">Escrow</td><td style="padding:8px 12px;text-align:right;font-size:14px;color:#111827;">Waived — taxes &amp; insurance paid directly</td></tr>'
  : '<tr style="border-bottom:1px solid #f3f4f6;"><td style="padding:8px 12px;color:#6b7280;font-size:14px;">Escrow</td><td style="padding:8px 12px;text-align:right;font-size:14px;color:#111827;">Active</td></tr>';

const subject = 'Your Refinance is Underway – Adam Styer | Mortgage Solutions LP';

const html =
  '<div style="font-family:Arial,sans-serif;font-size:15px;color:#111827;max-width:600px;margin:0 auto;">' +
  '<p>Hi ' + borrowerFirst + coBorrowerSalutation + ',</p>' +
  '<p>Your refinance is underway. Below is a summary of your loan terms from the initial fees worksheet.</p>' +
  '<table style="width:100%;border-collapse:collapse;margin:20px 0;border:1px solid #e5e7eb;">' +
  '<thead><tr style="background:#f9fafb;"><th colspan="2" style="padding:12px;text-align:left;font-size:14px;color:#374151;font-weight:600;border-bottom:1px solid #e5e7eb;">Loan Summary</th></tr></thead>' +
  '<tbody>' +
  '<tr style="border-bottom:1px solid #f3f4f6;"><td style="padding:8px 12px;color:#6b7280;font-size:14px;">Loan Amount</td><td style="padding:8px 12px;text-align:right;font-size:14px;font-weight:600;color:#111827;">' + loanAmountFmt + '</td></tr>' +
  '<tr style="border-bottom:1px solid #f3f4f6;"><td style="padding:8px 12px;color:#6b7280;font-size:14px;">Interest Rate</td><td style="padding:8px 12px;text-align:right;font-size:14px;font-weight:600;color:#111827;">' + rate + '%</td></tr>' +
  '<tr style="border-bottom:1px solid #f3f4f6;"><td style="padding:8px 12px;color:#6b7280;font-size:14px;">Principal &amp; Interest</td><td style="padding:8px 12px;text-align:right;font-size:14px;color:#111827;">' + piPaymentFmt + '</td></tr>' +
  '<tr style="border-bottom:1px solid #f3f4f6;"><td style="padding:8px 12px;color:#6b7280;font-size:14px;">Est. Total Monthly Payment</td><td style="padding:8px 12px;text-align:right;font-size:14px;color:#111827;">' + totalMonthlyFmt + '</td></tr>' +
  '<tr style="border-bottom:1px solid #f3f4f6;"><td style="padding:8px 12px;color:#6b7280;font-size:14px;">' + cashLabel + '</td><td style="padding:8px 12px;text-align:right;font-size:14px;color:#111827;">' + cashAmt + '</td></tr>' +
  '<tr style="border-bottom:1px solid #f3f4f6;"><td style="padding:8px 12px;color:#6b7280;font-size:14px;">Rate Lock</td><td style="padding:8px 12px;text-align:right;font-size:14px;color:#111827;">' + lockPeriod + '</td></tr>' +
  escrowRow +
  '</tbody></table>' +
  '<p>Janie, our processor, will reach out shortly to collect the documents needed to get your file to underwriting. In the meantime, if you have any questions, call or text me at <a href="tel:5129566010">512-956-6010</a> or reply to this email.</p>' +
  '<p>Adam Styer<br>Senior Loan Officer | Mortgage Solutions LP<br>NMLS# 513013<br>(512) 956-6010<br><a href="mailto:adam@thestyerteam.com">adam@thestyerteam.com</a></p>' +
  '</div>';

return [{
  json: {
    subject,
    html,
    borrowerEmail,
    loanId,
    borrowerFirst,
    borrowerLast,
    loanAmountFmt,
    rate
  }
}];
